<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class Transaksi extends Model { protected $table='transaksi'; protected $primaryKey='id_transaksi'; protected $guarded=['id_transaksi','kode_transaksi','id_pelanggan','id_petugas','jenis_transaksi','subtotal','diskon','total','status']; protected function casts():array{return ['tanggal'=>'datetime','subtotal'=>'decimal:2','diskon'=>'decimal:2','total'=>'decimal:2','promo_value_snapshot'=>'decimal:2','created_at'=>'datetime','updated_at'=>'datetime'];} public function pelanggan(){return $this->belongsTo(Pelanggan::class,'id_pelanggan','id_pelanggan');} public function petugas(){return $this->belongsTo(Petugas::class,'id_petugas','id_petugas');} public function promo(){return $this->belongsTo(PromoMember::class,'id_promo','id_promo');} public function promoRedemption(){return $this->hasOne(PromoRedemption::class,'id_transaksi','id_transaksi');} public function servis(){return $this->hasOne(Servis::class,'id_transaksi','id_transaksi');} public function bookingCuci(){return $this->hasOne(BookingCuci::class,'id_transaksi','id_transaksi');} public function penjualanSparepart(){return $this->hasOne(PenjualanSparepart::class,'id_transaksi','id_transaksi');} public function penjualanMobil(){return $this->hasOne(PenjualanMobil::class,'id_transaksi','id_transaksi');} public function pembelianMobilBekas(){return $this->hasOne(PembelianMobilBekas::class,'id_transaksi','id_transaksi');} public function tradeIn(){return $this->hasOne(TradeIn::class,'id_transaksi','id_transaksi');} public function pembayarans(){return $this->hasMany(Pembayaran::class,'id_transaksi','id_transaksi');} public function gatewayPayments(){return $this->hasMany(PembayaranGateway::class,'id_transaksi','id_transaksi');} public function pesananMobilMember(){return $this->hasOne(PesananMobilMember::class,'id_transaksi','id_transaksi');} }
